package com.campusevents.ui;
import com.campusevents.model.*;import com.campusevents.service.AuthService;import javax.swing.*;import java.awt.*;
public class LoginFrame extends JFrame {private final JTextField email=new JTextField(22);private final JPasswordField pass=new JPasswordField(22);public LoginFrame(){super("Campus Events | Login");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(480,350);setLocationRelativeTo(null);JPanel p=new JPanel(new GridBagLayout());p.setBorder(BorderFactory.createEmptyBorder(25,35,25,35));GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(8,8,8,8);g.fill=GridBagConstraints.HORIZONTAL;g.gridx=0;g.gridy=0;g.gridwidth=2;JLabel title=new JLabel("Campus Event Portal");title.setFont(new Font("SansSerif",Font.BOLD,26));p.add(title,g);g.gridwidth=1;g.gridy++;p.add(new JLabel("Email"),g);g.gridx=1;p.add(email,g);g.gridx=0;g.gridy++;p.add(new JLabel("Password"),g);g.gridx=1;p.add(pass,g);g.gridx=0;g.gridy++;g.gridwidth=2;JButton login=new JButton("Sign in");p.add(login,g);g.gridy++;JButton signup=new JButton("Create student account");p.add(signup,g);g.gridy++;p.add(new JLabel("Demo admin: admin@campus.local / Admin@123"),g);setContentPane(p);login.addActionListener(e->login());signup.addActionListener(e->new RegisterDialog(this).setVisible(true));}private void login(){try{User u=new AuthService().login(email.getText(),new String(pass.getPassword()));dispose();if(u instanceof Admin)new AdminFrame(u).setVisible(true);else new StudentFrame((Student)u).setVisible(true);}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Login failed",JOptionPane.ERROR_MESSAGE);}}}
